.darma-loader-three-dots-hourglass{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-rise: calc(var(--loader-size, 56px) / 3.5);
  position:relative;
  display:inline-block;
  width:var(--td-dot);
  height:var(--td-dot);
}
.darma-loader-three-dots-hourglass::before,
.darma-loader-three-dots-hourglass::after{
  content:"";
  position:absolute;
  left:0;
  top:0;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
}
.darma-loader-three-dots-hourglass::before{
  background-color:var(--loader-color, #6366f1);
  animation:darma-loader-three-dots-hourglass-td-hourglass-up var(--loader-speed, 1.8s) infinite ease-in-out;
}
.darma-loader-three-dots-hourglass::after{
  background-color:var(--loader-secondary-color, #a5b4fc);
  animation:darma-loader-three-dots-hourglass-td-hourglass-down var(--loader-speed, 1.8s) infinite ease-in-out;
}
@keyframes darma-loader-three-dots-hourglass-td-hourglass-up{
  0%,100%{transform:translateY(calc(var(--td-rise) * -1)) scale(1)}
  50%{transform:translateY(var(--td-rise)) scale(.7)}
}
@keyframes darma-loader-three-dots-hourglass-td-hourglass-down{
  0%,100%{transform:translateY(var(--td-rise)) scale(.7)}
  50%{transform:translateY(calc(var(--td-rise) * -1)) scale(1)}
}

